package com.example.ayni.sync.service;import com.example.ayni.help.dto.HelpPostResponse;import com.example.ayni.help.dto.HelpRequests;import com.example.ayni.help.service.HelpService;import com.example.ayni.listing.dto.ListingRequests;import com.example.ayni.listing.dto.ListingResponse;import com.example.ayni.listing.service.ListingService;import com.example.ayni.sync.dto.SyncRequests;import com.example.ayni.sync.model.SyncOperation;import com.example.ayni.sync.repository.SyncOperationRepository;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @Transactional public class SyncService{private final SyncOperationRepository operations;private final ListingService listings;private final HelpService help;private final ObjectMapper json;public SyncService(SyncOperationRepository operations,ListingService listings,HelpService help,ObjectMapper json){this.operations=operations;this.listings=listings;this.help=help;this.json=json;}public List<SyncRequests.Result> sync(UUID user,SyncRequests.Batch batch){return batch.operations().stream().map(op->process(user,op)).toList();}private SyncRequests.Result process(UUID user,SyncRequests.Operation input){var previous=operations.findByOperationId(input.operationId());if(previous.isPresent()){var p=previous.get();return new SyncRequests.Result(p.getOperationId(),p.getStatus(),p.getEntityId());}SyncOperation saved=operations.save(new SyncOperation(user,input.operationId(),input.operationType()));try{UUID entity=switch(input.operationType()){case "CREATE_LISTING"->listing(user,input);case "CREATE_HELP_POST"->help(user,input);default->throw new IllegalArgumentException("Tipo de operación no soportado");};saved.complete(entity);return new SyncRequests.Result(input.operationId(),"SYNCED",entity);}catch(RuntimeException e){saved.fail();throw e;}}private UUID listing(UUID user,SyncRequests.Operation op){ListingRequests.Create request=json.convertValue(op.data(),ListingRequests.Create.class);ListingResponse created=listings.create(user,request);return created.id();}private UUID help(UUID user,SyncRequests.Operation op){HelpRequests.Create request=json.convertValue(op.data(),HelpRequests.Create.class);HelpPostResponse created=help.create(user,request);return created.id();}}
